+/**
+ * Sanitize SVG content to prevent XSS attacks.
+ * Removes dangerous elements and attributes from SVG documents.
+ */
+
+/**
+ * List of dangerous SVG/HTML elements that could execute scripts.
+ */
+const DANGEROUS_ELEMENTS = new Set([
+    'script',
+    'use',
+    'foreignObject',
+    'animate',
+    'set',
+    'animateMotion',
+    'animateTransform',
+    'animateColor',
+    'handler',
+    'listener',
+    'prefetch',
+    'discard'
+]);
+
+/**
+ * List of dangerous attributes that could execute scripts.
+ */
+const DANGEROUS_ATTRIBUTES = [
+    /^on/i,           // Event handlers (onclick, onload, onerror, etc.)
+    /^xlink:href$/i,  // Can contain javascript: URLs
+    /^href$/i,        // Can contain javascript: URLs
+    /^src$/i,         // Can contain javascript: URLs
+    /^action$/i,      // Form action
+    /^formaction$/i,  // Form action override
+    /^data$/i,        // Object data
+    /^poster$/i,      // Video poster
+    /^background$/i   // Background URL
+];
+
+/**
+ * Check if an attribute value contains a dangerous URL scheme.
+ * @param {string} value - The attribute value to check.
+ * @returns {boolean} True if the value is dangerous.
+ */
+const isDangerousUrl = value => {
+    const trimmed = value.replace(/[\x00-\x20]+/g, '').toLowerCase();
+    return /^javascript:/i.test(trimmed) ||
+           /^vbscript:/i.test(trimmed) ||
+           /^data:text\/html/i.test(trimmed);
+};
+
+/**
+ * Recursively sanitize an SVG DOM element.
+ * @param {Element} element - The element to sanitize.
+ */
+const sanitizeElement = element => {
+    // Collect children first to avoid live NodeList issues
+    const children = Array.from(element.childNodes);
+    for (const child of children) {
+        if (child.nodeType === child.ELEMENT_NODE) {
+            const tagName = child.tagName ? child.tagName.toLowerCase().replace(/.*:/, '') : '';
+            if (DANGEROUS_ELEMENTS.has(tagName)) {
+                element.removeChild(child);
+            } else {
+                // Sanitize attributes
+                const attrs = Array.from(child.attributes || []);
+                for (const attr of attrs) {
+                    const attrName = attr.name.toLowerCase();
+                    const isDangerous = DANGEROUS_ATTRIBUTES.some(pattern => pattern.test(attrName));
+                    if (isDangerous || isDangerousUrl(attr.value)) {
+                        child.removeAttribute(attr.name);
+                    }
+                }
+                sanitizeElement(child);
+            }
+        }
+    }
+};
+
+/**
+ * Sanitize an SVG string to remove potentially dangerous content.
+ * @param {string} svgString - The SVG string to sanitize.
+ * @returns {string} The sanitized SVG string.
+ */
+const sanitizeSvgString = svgString => {
+    const parser = new DOMParser();
+    const doc = parser.parseFromString(svgString, 'image/svg+xml');
+    const svgElement = doc.documentElement;
+    sanitizeElement(svgElement);
+    const serializer = new XMLSerializer();
+    return serializer.serializeToString(doc);
+};
+
+module.exports = {sanitizeSvgString};
