+package org.apache.streampipes.commons.networking;
+
+import org.slf4j.Logger;
+import org.slf4j.LoggerFactory;
+
+import java.net.InetAddress;
+import java.net.MalformedURLException;
+import java.net.URL;
+import java.net.UnknownHostException;
+import java.util.Arrays;
+import java.util.List;
+
+public class SsrfValidator {
+
+  private static final Logger LOG = LoggerFactory.getLogger(SsrfValidator.class);
+
+  private static final List<String> ALLOWED_SCHEMES = Arrays.asList("http", "https");
+
+  /**
+   * Validates that the given URL string is safe to fetch (not an SSRF target).
+   * Checks:
+   * 1. URL scheme is http or https only
+   * 2. Resolved IP is not a private/loopback/link-local address
+   *
+   * @param urlString the URL to validate
+   * @throws IllegalArgumentException if the URL is not safe
+   */
+  public static void validate(String urlString) throws IllegalArgumentException {
+    if (urlString == null || urlString.isEmpty()) {
+      throw new IllegalArgumentException("URL must not be null or empty");
+    }
+
+    URL url;
+    try {
+      url = new URL(urlString);
+    } catch (MalformedURLException e) {
+      throw new IllegalArgumentException("Invalid URL: " + e.getMessage());
+    }
+
+    String scheme = url.getProtocol();
+    if (!ALLOWED_SCHEMES.contains(scheme.toLowerCase())) {
+      throw new IllegalArgumentException(
+          "URL scheme '" + scheme + "' is not allowed. Only http and https are permitted.");
+    }
+
+    String host = url.getHost();
+    if (host == null || host.isEmpty()) {
+      throw new IllegalArgumentException("URL host must not be empty");
+    }
+
+    InetAddress address;
+    try {
+      address = InetAddress.getByName(host);
+    } catch (UnknownHostException e) {
+      throw new IllegalArgumentException("Cannot resolve host: " + host);
+    }
+
+    if (isInternalAddress(address)) {
+      throw new IllegalArgumentException(
+          "Requests to internal/private network addresses are not permitted");
+    }
+  }
+
+  /**
+   * Returns true if the address is a loopback, site-local, link-local,
+   * or any other non-routable address.
+   */
+  private static boolean isInternalAddress(InetAddress address) {
+    return address.isLoopbackAddress()
+        || address.isSiteLocalAddress()
+        || address.isLinkLocalAddress()
+        || address.isAnyLocalAddress()
+        || address.isMulticastAddress()
+        || isDocumentationOrReserved(address);
+  }
+
+  private static boolean isDocumentationOrReserved(InetAddress address) {
+    byte[] addr = address.getAddress();
+    // 100.64.0.0/10 - Shared Address Space (RFC 6598)
+    if (addr.length == 4) {
+      int first = addr[0] & 0xFF;
+      int second = addr[1] & 0xFF;
+      if (first == 100 && (second & 0xC0) == 64) {
+        return true;
+      }
+      // 192.0.2.0/24, 198.51.100.0/24, 203.0.113.0/24 (TEST-NET)
+      if (first == 192 && second == 0 && (addr[2] & 0xFF) == 2) {
+        return true;
+      }
+      if (first == 198 && second == 51 && (addr[2] & 0xFF) == 100) {
+        return true;
+      }
+      if (first == 203 && second == 0 && (addr[2] & 0xFF) == 113) {
+        return true;
+      }
+    }
+    return false;
+  }
+}
